"""RoboCasa365 (eden_robocasa365) object and kitchen-layout options.

Auto-generated from the exported eden_robocasa365 scenes. Unlike
:mod:`eden.options.objects.robocasa`, where all styles of a layout share one
dofs_name, dofs_name here is per scene: RoboCasa365 picks different appliance
models (fridge/dishwasher/oven) per style, so the joint sets differ.
"""

from __future__ import annotations

from typing import ClassVar

from eden.options.entities import EntityOptions
from eden.utils.registry import Registry

ROBOCASA365_ACCESSORIES_REGISTRY = Registry("ROBOCASA365_ACCESSORIES")
ROBOCASA365_KITCHEN_REGISTRY = Registry("ROBOCASA365_KITCHEN")


class _Robocasa365Options(EntityOptions):
    """RoboCasa365 release (https://robocasa.ai/) — articulated appliances."""

    up: tuple[int, int, int] = (0, 0, 1)
    front: tuple[int, int, int] = (0, -1, 0)
    is_fixed_base: bool = True

    registry: str = "Kashu7100"
    dataset: str = "eden_robocasa365"
    assets_subdir: ClassVar[str] = "robocasa365"


# ──────────────────────────────────────────────────────────────────────────────
# 10 layouts x 12 styles = 120 kitchen scenes
# ──────────────────────────────────────────────────────────────────────────────

# --- LAYOUT001 (1/10) ---


